1	import { defineHook } from "../lib/hook";
2	import { DOM_IDS, findElement, requireElement } from "../lib/dom_ids";
3	import { PersistedRecord } from "../lib/persisted_record";
4	import {
5	  type ProgressBuffer,
6	  attachProgressBuffer,
7	} from "../lib/progress_buffer";
8	import { attachScrubber, fractionAt } from "../lib/scrubber";
9	import { scrollFollow } from "../lib/scroll_follow";
10	import { readerSettings } from "../lib/reader_settings_store";
11	import { cycleOption } from "../lib/cycle_option";
12	import {
13	  type JsonValue,
14	  type WordTiming,
15	  isJsonObject,
16	  parseWordTimings,
17	  wordSelector,
18	} from "../lib/types";
19	import { attachWordMenu } from "./word_menu";
20	
21	interface AudioPlayerDataset {
22	  audioUrl: string;
23	  timingsUrl: string;
24	  initialPosition?: string;
25	  bookId?: string;
26	  bookTitle?: string;
27	  chapterTitle?: string;
28	  chapterId?: string;
29	  nextChapterId?: string;
30	  nextAudioUrl?: string;
31	  nextTimingsUrl?: string;
32	  nextChapterTitle?: string;
33	  prevChapterId?: string;
34	  prevAudioUrl?: string;
35	  prevTimingsUrl?: string;
36	  prevChapterTitle?: string;
37	}
38	
39	interface PlayerPrefs {
40	  readonly speed: number;
41	  readonly volume: number;
42	  readonly collapsed: boolean;
43	}
44	
45	const PLAYER_PREFS_DEFAULTS: PlayerPrefs = Object.freeze({
46	  speed: 1,
47	  volume: 1,
48	  collapsed: false,
49	});
50	
51	const PLAYER_PREFS_KEY = "readaloud-player-prefs";
52	
53	const SPEEDS = [0.5, 0.75, 1, 1.25, 1.5, 1.75, 2] as const;
54	
55	const POSITION_REPORT_INTERVAL_MS = 5000;
56	const SKIP_SECONDS = 10;
57	const AUTO_SCROLL_GRACE_MS = 800;
58	
59	// Play/pause button glyphs. The LV template renders ▶ (as &#9654;) as the
60	// static default; the hook overwrites textContent on every audio play/pause.
61	const PLAY_GLYPH = "▶";
62	const PAUSE_GLYPH = "❚❚";
63	
64	function coercePlayerPrefs(raw: JsonValue): Partial<PlayerPrefs> {
65	  if (!isJsonObject(raw)) return {};
66	  const out: { -readonly [K in keyof PlayerPrefs]?: PlayerPrefs[K] } = {};
67	  if (typeof raw.speed === "number") out.speed = raw.speed;
68	  if (typeof raw.volume === "number") out.volume = raw.volume;
69	  if (typeof raw.collapsed === "boolean") out.collapsed = raw.collapsed;
70	  return out;
71	}
72	
73	function migrateLegacyPlayerPrefs(): void {
74	  if (localStorage.getItem(PLAYER_PREFS_KEY) !== null) return;
75	  const legacySpeed = localStorage.getItem("readaloud-playback-speed");
76	  const legacyVolume = localStorage.getItem("readaloud-volume");
77	  const legacyCollapsed = localStorage.getItem("readaloud-player-collapsed");
78	  if (legacySpeed === null && legacyVolume === null && legacyCollapsed === null)
79	    return;
80	  const migrated: PlayerPrefs = {
81	    speed:
82	      legacySpeed !== null
83	        ? Number.parseFloat(legacySpeed)
84	        : PLAYER_PREFS_DEFAULTS.speed,
85	    volume:
86	      legacyVolume !== null
87	        ? Number.parseFloat(legacyVolume)
88	        : PLAYER_PREFS_DEFAULTS.volume,
89	    collapsed: legacyCollapsed === "true",
90	  };
91	  localStorage.setItem(PLAYER_PREFS_KEY, JSON.stringify(migrated));
92	}
93	
94	migrateLegacyPlayerPrefs();
95	const playerPrefs = new PersistedRecord<PlayerPrefs>(
96	  PLAYER_PREFS_KEY,
97	  PLAYER_PREFS_DEFAULTS,
98	  coercePlayerPrefs,
99	);
100	
101	function findActiveWord(
102	  timings: ReadonlyArray<WordTiming>,
103	  ms: number,
104	): number {
105	  let idx = -1;
106	  let lo = 0;
107	  let hi = timings.length - 1;
108	  while (lo <= hi) {
109	    const mid = (lo + hi) >>> 1;
110	    const t = timings[mid];
111	    if (!t) break;
112	    if (ms >= t.startMs && ms < t.endMs) {
113	      idx = mid;
114	      break;
115	    } else if (ms < t.startMs) {
116	      hi = mid - 1;
117	    } else {
118	      idx = mid;
119	      lo = mid + 1;
120	    }
121	  }
122	  if (idx >= 0 && idx < timings.length - 1) {
123	    const next = timings[idx + 1];
124	    if (next && ms >= next.startMs) idx += 1;
125	  }
126	  return idx;
127	}
128	
129	function formatTime(secs: number): string {
130	  if (!Number.isFinite(secs) || secs < 0) return "0:00";
131	  const m = Math.floor(secs / 60);
132	  const s = Math.floor(secs % 60);
133	  return `${m}:${s < 10 ? "0" : ""}${s}`;
134	}
135	
136	// Monotonically increasing player-instance ID. Each hook mount gets one;
137	// shows up in every log line so we can tell apart pre-/post-remount
138	// instances when reading the browser console after the fact.
139	let nextPlayerId = 1;
140	
141	export const AudioPlayerHook = defineHook<HTMLDivElement, AudioPlayerDataset>(
142	  (ctx) => {
143	    const audio = requireElement(DOM_IDS.AUDIO_ELEMENT, HTMLAudioElement);
144	    const playPauseBtn = requireElement(DOM_IDS.PLAY_PAUSE_BTN, HTMLElement);
145	    const timeDisplay = findElement(DOM_IDS.TIME_DISPLAY, HTMLElement);
146	    const textContainer = findElement(DOM_IDS.CHAPTER_TEXT, HTMLElement);
147	    const resyncBtn = findElement(DOM_IDS.RESYNC_BTN, HTMLElement);
148	    const speedBadge = findElement(DOM_IDS.SPEED_BADGE, HTMLElement);
149	
150	    if (!audio || !playPauseBtn) return;
151	
152	    const playerId = nextPlayerId++;
153	    // Detailed always-on logging for autoplay debugging. When the user
154	    // reports a symptom ("phone woke up at 11:07 and audio was at 0:00")
155	    // these lines + the chapter/book ids let us line up the JS-side state
156	    // machine with server logs (see reader_live.ex Logger.info calls).
157	    type LogValue = string | number | boolean | null | undefined;
158	    const log = (event: string, extra?: Record<string, LogValue>): void => {
159	      const wall = new Date().toISOString();
160	      const t =
161	        typeof performance !== "undefined"
162	          ? Math.round(performance.now())
163	          : Date.now();
164	      const base: Record<string, LogValue> = {
165	        player: playerId,
166	        chapter: ctx.dataset.chapterId,
167	        t,
168	      };
169	      if (extra) Object.assign(base, extra);
170	      // Always-on autoplay telemetry per the comment above; this is
171	      // intentional production logging, not debug residue.
172	      // ast-grep-ignore: no-console-log
173	      console.log(`[autoplay ${wall}] ${event}`, base);
174	    };
175	
176	    let timings: ReadonlyArray<WordTiming> = [];
177	    let currentWordIndex = -1;
178	    let lastReportedMs = -1;
179	    let rafId: number | undefined;
180	    let wordMenuCleanup: (() => void) | undefined;
181	    let intersectionObserver: IntersectionObserver | undefined;
182	
183	    // Durable position-observation buffer. The hook owns the lifetime;
184	    // localStorage owns the cross-mount state (so a buffered observation
185	    // from before a LV remount or page-hide drains on the next mount).
186	    //
187	    // `data-book-id` is set by the LV template and is part of the hook's
188	    // contract — if it's ever missing or unparseable, that's a template
189	    // bug and we want to fail loudly at mount, not silently no-op every
190	    // observation downstream.
191	    const bookId = Number.parseInt(ctx.dataset.bookId ?? "", 10);
192	    if (!Number.isFinite(bookId)) {
193	      throw new Error(
194	        "AudioPlayerHook: data-book-id is missing or unparseable",
195	      );
196	    }
197	    const progress: ProgressBuffer = attachProgressBuffer({
198	      bookId,
199	      beaconUrl: `/api/books/${bookId}/progress`,
200	      pushObservations: (observations) => {
201	        ctx.pushEvent("progress_observations", { observations });
202	      },
203	    });
204	    ctx.onDestroy(() => progress.detach());
205	
206	    const updateTimeDisplay = (): void => {
207	      if (!timeDisplay) return;
208	      timeDisplay.textContent = `${formatTime(audio.currentTime)} / ${formatTime(audio.duration)}`;
209	    };
210	
211	    const updateSpeedBadge = (speed: number): void => {
212	      if (!speedBadge) return;
213	      speedBadge.textContent = speed === 1 ? "1x" : `${speed}x`;
214	    };
215	
216	    const cycleSpeed = (direction: "up" | "down"): void => {
217	      const closest = SPEEDS.reduce((best, s) =>
218	        Math.abs(s - audio.playbackRate) < Math.abs(best - audio.playbackRate)
219	          ? s
220	          : best,
221	      );
222	      playerPrefs.set({ speed: cycleOption(SPEEDS, closest, direction) });
223	    };
224	
225	    const togglePlayback = (): void => {
226	      if (audio.paused) audio.play();
227	      else audio.pause();
228	    };
229	
230	    const seekToWordIndex = (idx: number): void => {
231	      const t = timings[idx];
232	      if (!t) return;
233	      audio.currentTime = t.startMs / 1000;
234	      if (audio.paused) audio.play();
235	    };
236	
237	    // Word highlighting with auto-scroll
238	    const highlightWord = (ms: number): void => {
239	      if (!textContainer || timings.length === 0) return;
240	      const idx = findActiveWord(timings, ms);
241	      if (idx === currentWordIndex) return;
242	
243	      if (currentWordIndex >= 0) {
244	        const old = textContainer.querySelector<HTMLElement>(
245	          wordSelector(currentWordIndex),
246	        );
247	        old?.classList.remove("word-active");
248	        old?.classList.add("word-spoken");
249	      }
250	
251	      if (idx >= 0) {
252	        const next = textContainer.querySelector<HTMLElement>(
253	          wordSelector(idx),
254	        );
255	        if (next) {
256	          next.classList.add("word-active");
257	          next.classList.remove("word-spoken");
258	
259	          if (!scrollFollow.get().autoScrollPaused) {
260	            scrollFollow.beginAutoScroll(AUTO_SCROLL_GRACE_MS);
261	            next.scrollIntoView({ behavior: "smooth", block: "center" });
262	            if (intersectionObserver) {
263	              intersectionObserver.disconnect();
264	              intersectionObserver.observe(next);
265	            }
266	          }
267	        }
268	      }
269	
270	      if (idx > currentWordIndex) {
271	        for (let i = Math.max(0, currentWordIndex); i < idx; i++) {
272	          const el = textContainer.querySelector<HTMLElement>(wordSelector(i));
273	          if (el) {
274	            el.classList.remove("word-active");
275	            el.classList.add("word-spoken");
276	          }
277	        }
278	      } else if (idx >= 0 && idx < currentWordIndex) {
279	        for (let i = idx + 1; i <= currentWordIndex; i++) {
280	          const el = textContainer.querySelector<HTMLElement>(wordSelector(i));
281	          if (el) el.classList.remove("word-spoken", "word-active");
282	        }
283	      }
284	
285	      currentWordIndex = idx;
286	    };
287	
288	    const startHighlightLoop = (): void => {
289	      const tick = (): void => {
290	        if (!audio.paused) {
291	          highlightWord(audio.currentTime * 1000);
292	          rafId = requestAnimationFrame(tick);
293	        }
294	      };
295	      rafId = requestAnimationFrame(tick);
296	    };
297	
298	    const stopHighlightLoop = (): void => {
299	      if (rafId !== undefined) {
300	        cancelAnimationFrame(rafId);
301	        rafId = undefined;
302	      }
303	    };
304	
305	    const volSlider = ctx.el.querySelector<HTMLInputElement>(
306	      "[data-volume-slider]",
307	    );
308	
309	    // Player prefs → DOM. Bound to the store so chapter-swap re-renders can't
310	    // desync the slider, the speed badge, or the collapsed class from the
311	    // user's actual preference. The audio element's playbackRate/volume are
312	    // also re-applied here; src changes can reset playbackRate, so the
313	    // loadedmetadata handler below re-runs apply for that case.
314	    const applyPlayerPrefs = (p: Readonly<PlayerPrefs>): void => {
315	      audio.playbackRate = p.speed;
316	      audio.volume = p.volume;
317	      updateSpeedBadge(p.speed);
318	      if (volSlider) volSlider.value = String(p.volume);
319	      ctx.el.classList.toggle("collapsed", p.collapsed);
320	    };
321	    ctx.bindStore(playerPrefs, applyPlayerPrefs);
322	
323	    // The <audio> element has phx-update="ignore" so it's preserved across
324	    // chapter switches (push_patch) AND across LV reconnect/re-mount. The
325	    // hook itself, however, is destroyed and re-mounted on a re-mount —
326	    // so on mount we may find an <audio> element that's already loaded
327	    // (and possibly mid-playback) from a previous hook instance. In that
328	    // case we MUST NOT touch its src — doing so would interrupt the
329	    // user's listening session, which is exactly the bug we're chasing
330	    // with sleeping-mobile autoplay (LV WebSocket times out → re-mount on
331	    // wake → forced reload → 00:00/00:00).
332	    //
333	    // Heuristic: only set src if the element doesn't have one yet (or
334	    // has the page URL, the default for an unset <audio>). If it has
335	    // any other src — network URL, or a `blob:` URL prefetched by a
336	    // previous hook instance — leave it alone.
337	    const wantSrc = ctx.dataset.audioUrl;
338	    const existingSrc = audio.src;
339	    const hasMeaningfulSrc =
340	      existingSrc !== "" &&
341	      existingSrc !== window.location.href &&
342	      existingSrc !== `${window.location.origin}/`;
343	    log("mount", {
344	      hasMeaningfulSrc,
345	      existingSrcKind: existingSrc.startsWith("blob:")
346	        ? "blob"
347	        : existingSrc === "" || existingSrc === window.location.href
348	          ? "empty"
349	          : "url",
350	      audioPaused: audio.paused,
351	      audioCurrentTime: audio.currentTime,
352	      audioReadyState: audio.readyState,
353	      autoNextChapter: readerSettings.get().autoNextChapter,
354	      hasNext: !!ctx.dataset.nextAudioUrl,
355	      hasPrev: !!ctx.dataset.prevAudioUrl,
356	      bookTitle: ctx.dataset.bookTitle,
357	      chapterTitle: ctx.dataset.chapterTitle,
358	    });
359	    if (!hasMeaningfulSrc) {
360	      log("set-initial-src");
361	      audio.src = wantSrc;
362	      audio.load();
363	    } else {
364	      log("preserve-existing-src");
365	    }
366	
367	    ctx.on(audio, "loadedmetadata", () => {
368	      applyPlayerPrefs(playerPrefs.get());
369	      updateTimeDisplay();
370	      updateMediaSessionPosition();
371	    });
372	    ctx.on(audio, "durationchange", updateTimeDisplay);
373	
374	    // Word timings — fetched on mount and re-fetched whenever we swap to a
375	    // new chapter via swapToChapter().
376	    const fetchTimings = (url: string): void => {
377	      timings = [];
378	      currentWordIndex = -1;
379	      fetch(url)
380	        .then((r) => r.json())
381	        .then((data: JsonValue) => {
382	          timings = parseWordTimings(data);
383	          if (textContainer && !wordMenuCleanup)
384	            wordMenuCleanup = attachWordMenu(textContainer);
385	        })
386	        .catch((err: Error) =>
387	          console.error("AudioPlayer: failed to load timings", err),
388	        );
389	    };
390	    fetchTimings(ctx.dataset.timingsUrl);
391	
392	    // Restore initial position — only on a fresh load. On re-mount of an
393	    // already-playing element we'd otherwise rewind the user back to a
394	    // saved position from a different LV session.
395	    const initialMs = Number.parseInt(ctx.dataset.initialPosition ?? "0", 10);
396	    if (initialMs > 0 && !hasMeaningfulSrc) {
397	      ctx.on(
398	        audio,
399	        "loadedmetadata",
400	        () => {
401	          audio.currentTime = initialMs / 1000;
402	        },
403	        { once: true },
404	      );
405	    }
406	
407	    // --- Media Session API ----------------------------------------------
408	    // Registers the OS-level lock-screen / notification controls. Without
409	    // this, a sleeping mobile device has no native "next chapter" button
410	    // and the WebSocket-bound LV nav often fails when the device wakes.
411	    // With this, the OS gives us a working next/prev button even when JS
412	    // is throttled, and the audio session keeps the lock screen UI alive
413	    // across chapter swaps (since we reuse the same <audio> element).
414	    const ms =
415	      typeof navigator !== "undefined" && "mediaSession" in navigator
416	        ? navigator.mediaSession
417	        : null;
418	
419	    const updateMediaSessionMetadata = (): void => {
420	      if (!ms) return;
421	      ms.metadata = new MediaMetadata({
422	        title: ctx.dataset.chapterTitle ?? "",
423	        artist: ctx.dataset.bookTitle ?? "",
424	        album: ctx.dataset.bookTitle ?? "",
425	      });
426	    };
427	
428	    const updateMediaSessionPosition = (): void => {
429	      if (!ms?.setPositionState) return;
430	      if (!Number.isFinite(audio.duration) || audio.duration <= 0) return;
431	      try {
432	        ms.setPositionState({
433	          duration: audio.duration,
434	          position: Math.min(audio.currentTime, audio.duration),
435	          playbackRate: audio.playbackRate || 1,
436	        });
437	      } catch {
438	        // Some browsers throw on invalid positions; ignore.
439	      }
440	    };
441	
442	    // --- Next-chapter prefetch -----------------------------------------
443	    // Mobile browsers (iOS Safari especially) suspend network fetches
444	    // when the screen locks. If we wait until `ended` to fetch the next
445	    // chapter's audio, the request stalls and audio.play() never gets a
446	    // valid resource — exactly the bug we're chasing. So while the
447	    // current chapter is still playing (and the device presumably
448	    // awake), download the next chapter's audio fully into a Blob URL.
449	    // On `ended` we swap to the in-memory blob — no network needed.
450	    let currentBlobUrl: string | null = null; // points to in-use audio.src
451	    let prefetchedBlobUrl: string | null = null;
452	    let prefetchedFor: string | null = null;
453	    let prefetchAbort: AbortController | null = null;
454	
455	    const tryStartPrefetch = (): void => {
456	      if (!readerSettings.get().autoNextChapter) return;
457	      const url = ctx.dataset.nextAudioUrl;
458	      if (!url) return;
459	      // Already done or in flight for the same URL? Skip.
460	      if (prefetchedBlobUrl && prefetchedFor === url) return;
461	      if (prefetchAbort && prefetchedFor === url) return;
462	      // Target URL changed (e.g. user manually jumped chapters) — drop
463	      // any in-flight or stale-blob state and restart.
464	      if (prefetchAbort) {
465	        log("prefetch-abort-stale", { for: prefetchedFor });
466	        prefetchAbort.abort();
467	        prefetchAbort = null;
468	      }
469	      if (prefetchedBlobUrl) {
470	        log("prefetch-revoke-stale", { for: prefetchedFor });
471	        URL.revokeObjectURL(prefetchedBlobUrl);
472	        prefetchedBlobUrl = null;
473	      }
474	      prefetchedFor = url;
475	      const abort = new AbortController();
476	      prefetchAbort = abort;
477	      log("prefetch-start", { url });
478	      const startedAt = performance.now();
479	      fetch(url, { signal: abort.signal })
480	        .then((r) => {
481	          if (!r.ok) throw new Error(`HTTP ${r.status}`);
482	          return r.blob();
483	        })
484	        .then((blob) => {
485	          prefetchAbort = null;
486	          if (prefetchedFor !== url) {
487	            log("prefetch-discard-target-changed", {
488	              completedFor: url,
489	              currentTarget: prefetchedFor,
490	            });
491	            return;
492	          }
493	          prefetchedBlobUrl = URL.createObjectURL(blob);
494	          log("prefetch-done", {
495	            url,
496	            bytes: blob.size,
497	            durationMs: Math.round(performance.now() - startedAt),
498	          });
499	        })
500	        .catch((err: Error) => {
501	          prefetchAbort = null;
502	          if (err.name !== "AbortError") {
503	            log("prefetch-fail", { url, error: String(err) });
504	            console.warn("AudioPlayer: next-chapter prefetch failed", err);
505	            // Reset prefetchedFor so we can retry later (e.g. on next
506	            // timeupdate) instead of being stuck thinking we're done.
507	            if (prefetchedFor === url) prefetchedFor = null;
508	          } else {
509	            log("prefetch-aborted", { url });
510	          }
511	        });
512	    };
513	
514	    // Swap to a different chapter without unmounting the player. Used by
515	    // both the auto-next-on-ended path and (if invoked from outside) by
516	    // server-pushed chapter changes. Critically: same <audio> element, so
517	    // the OS audio session is preserved and lock-screen playback continues
518	    // without requiring a new user gesture.
519	    const swapToChapter = (
520	      audioUrl: string,
521	      timingsUrl: string,
522	      chapterTitle: string,
523	    ): void => {
524	      log("swap-to-chapter", {
525	        srcKind: audioUrl.startsWith("blob:") ? "blob" : "url",
526	        chapterTitle,
527	        audioPaused: audio.paused,
528	      });
529	      audio.src = audioUrl;
530	      audio.load();
531	      // Update title eagerly so the lock screen shows the new chapter name
532	      // even before the LV push_patch round-trip lands.
533	      if (ms) {
534	        ms.metadata = new MediaMetadata({
535	          title: chapterTitle,
536	          artist: ctx.dataset.bookTitle ?? "",
537	          album: ctx.dataset.bookTitle ?? "",
538	        });
539	      }
540	      fetchTimings(timingsUrl);
541	      audio
542	        .play()
543	        .then(() => log("swap-play-ok"))
544	        .catch((err: Error) => {
545	          log("swap-play-blocked", { error: String(err) });
546	          console.warn("AudioPlayer: chapter-swap play blocked", err);
547	        });
548	    };
549	
550	    // Build a /books/:bookId/read/:chapterId?nav=internal URL by swapping
551	    // the chapter id in the current pathname. The current path always
552	    // matches /books/:bookId/read/:N (we're rendering the reader LV), so
553	    // a regex replace is enough — no need to thread book_id through the
554	    // hook's dataset. Returns null if the pathname isn't on the reader.
555	    const buildReaderUrl = (chapterId: string): string | null => {
556	      const path = window.location.pathname;
557	      if (!/\/books\/\d+\/read\/\d+/.test(path)) return null;
558	      return (
559	        path.replace(/\/read\/\d+/, `/read/${chapterId}`) + "?nav=internal"
560	      );
561	    };
562	
563	    const goToNextChapter = (): boolean => {
564	      const networkUrl = ctx.dataset.nextAudioUrl;
565	      const timingsUrl = ctx.dataset.nextTimingsUrl;
566	      const title = ctx.dataset.nextChapterTitle ?? "";
567	      const nextChapterId = ctx.dataset.nextChapterId;
568	      if (!networkUrl || !timingsUrl || !nextChapterId) {
569	        log("next-chapter-blocked-no-target", {
570	          hasUrl: !!networkUrl,
571	          hasTimings: !!timingsUrl,
572	          hasChapterId: !!nextChapterId,
573	        });
574	        return false;
575	      }
576	
577	      // Use the prefetched in-memory blob if it's for THIS URL — this is
578	      // the whole point of prefetch and is what makes background-tab
579	      // autoplay actually work. Fall back to the network URL otherwise
580	      // (e.g. desktop user who never triggered prefetch).
581	      const audioUrl =
582	        prefetchedBlobUrl !== null && prefetchedFor === networkUrl
583	          ? prefetchedBlobUrl
584	          : networkUrl;
585	      const useBlob = audioUrl !== networkUrl;
586	      log("go-to-next-chapter", {
587	        useBlob,
588	        prefetchedFor,
589	        prefetchInFlight: prefetchAbort !== null,
590	        toTitle: title,
591	      });
592	
593	      // The blob currently in use as audio.src (if any) is being replaced
594	      // — revoke it so we don't leak ~tens of MB per chapter swap.
595	      if (currentBlobUrl) URL.revokeObjectURL(currentBlobUrl);
596	      currentBlobUrl = useBlob ? audioUrl : null;
597	      // Detach the prefetched-blob slot since it's now the current one
598	      // (or we didn't use it). Either way, the next prefetch (for the
599	      // chapter after this) starts fresh.
600	      prefetchedBlobUrl = null;
601	      prefetchedFor = null;
602	      if (prefetchAbort) {
603	        prefetchAbort.abort();
604	        prefetchAbort = null;
605	      }
606	
607	      swapToChapter(audioUrl, timingsUrl, title);
608	
609	      // Update browser URL client-side BEFORE notifying the server. This
610	      // is the critical fix for sleeping-mobile autoplay: server-side
611	      // push_patch only updates the URL when its diff reaches the
612	      // client, which doesn't happen if the WebSocket is suspended (and
613	      // the LV process times out before delivery). With this pushState
614	      // the URL stays in sync with audio.src regardless of WS state, so
615	      // a refresh after wake lands on the chapter that's actually
616	      // playing — not the previous one.
617	      const newUrl = buildReaderUrl(nextChapterId);
618	      if (newUrl) {
619	        history.pushState({}, "", newUrl);
620	        log("history-pushstate", { url: newUrl });
621	      }
622	
623	      // Persist the pivot through the durable buffer. If the WS is
624	      // suspended (mobile lock — the original autoplay-stranding bug),
625	      // the buffer falls back to sendBeacon on visibilitychange:hidden
626	      // so the new chapter / 0:00 reset survives even with a dead WS.
627	      progress.observe({
628	        chapter_id: nextChapterId,
629	        audio_position_ms: 0,
630	        scroll_position: 0,
631	      });
632	
633	      // Tell the server to reload chapter assigns. `client_owned: true`
634	      // means JS owns BOTH the URL update (already pushState'd above)
635	      // AND the persistence write (already buffered above), so the
636	      // server skips its own push_patch and observe! — pushing twice
637	      // would create a duplicate history entry, and observing twice
638	      // would race with the buffered drain.
639	      log("push-event", { event: "next_chapter" });
640	      ctx.pushEvent("next_chapter", { client_owned: true });
641	      return true;
642	    };
643	
644	    const goToPrevChapter = (): boolean => {
645	      const url = ctx.dataset.prevAudioUrl;
646	      const timingsUrl = ctx.dataset.prevTimingsUrl;
647	      const title = ctx.dataset.prevChapterTitle ?? "";
648	      const prevChapterId = ctx.dataset.prevChapterId;
649	      if (!url || !timingsUrl || !prevChapterId) {
650	        log("prev-chapter-blocked-no-target");
651	        return false;
652	      }
653	      log("go-to-prev-chapter", { toTitle: title });
654	      swapToChapter(url, timingsUrl, title);
655	
656	      // Same client-side URL update + persistence as next-chapter; see
657	      // the comment block in goToNextChapter for the full rationale.
658	      const newUrl = buildReaderUrl(prevChapterId);
659	      if (newUrl) {
660	        history.pushState({}, "", newUrl);
661	        log("history-pushstate", { url: newUrl });
662	      }
663	
664	      progress.observe({
665	        chapter_id: prevChapterId,
666	        audio_position_ms: 0,
667	        scroll_position: 0,
668	      });
669	
670	      log("push-event", { event: "prev_chapter" });
671	      ctx.pushEvent("prev_chapter", { client_owned: true });
672	      return true;
673	    };
674	
675	    if (ms) {
676	      updateMediaSessionMetadata();
677	      const safeSet = (
678	        action: MediaSessionAction,
679	        handler: MediaSessionActionHandler | null,
680	      ): void => {
681	        try {
682	          ms.setActionHandler(action, handler);
683	        } catch {
684	          // Browser may not support this action — fine, skip it.
685	        }
686	      };
687	      safeSet("play", () => {
688	        audio.play().catch(() => {});
689	      });
690	      safeSet("pause", () => audio.pause());
691	      safeSet("seekbackward", (details) => {
692	        const delta = details.seekOffset ?? SKIP_SECONDS;
693	        audio.currentTime = Math.max(0, audio.currentTime - delta);
694	      });
695	      safeSet("seekforward", (details) => {
696	        const delta = details.seekOffset ?? SKIP_SECONDS;
697	        const max = Number.isFinite(audio.duration)
698	          ? audio.duration
699	          : Number.POSITIVE_INFINITY;
700	        audio.currentTime = Math.min(max, audio.currentTime + delta);
701	      });
702	      safeSet("seekto", (details) => {
703	        if (typeof details.seekTime === "number") {
704	          audio.currentTime = details.seekTime;
705	        }
706	      });
707	      // Only register next/prev when there's actually a target; otherwise
708	      // the OS UI shows greyed-out buttons (or nothing) which is correct.
709	      if (ctx.dataset.nextAudioUrl) {
710	        safeSet("nexttrack", () => {
711	          log("media-session-nexttrack");
712	          goToNextChapter();
713	        });
714	      } else {
715	        safeSet("nexttrack", null);
716	      }
717	      if (ctx.dataset.prevAudioUrl) {
718	        safeSet("previoustrack", () => {
719	          log("media-session-previoustrack");
720	          goToPrevChapter();
721	        });
722	      } else {
723	        safeSet("previoustrack", null);
724	      }
725	      ctx.onDestroy(() => {
726	        // Clear handlers + metadata so a stale player on a different page
727	        // doesn't get media-key events meant for nothing.
728	        const actions: readonly MediaSessionAction[] = [
729	          "play",
730	          "pause",
731	          "nexttrack",
732	          "previoustrack",
733	          "seekbackward",
734	          "seekforward",
735	          "seekto",
736	        ];
737	        for (const a of actions) {
738	          try {
739	            ms.setActionHandler(a, null);
740	          } catch {}
741	        }
742	        ms.metadata = null;
743	      });
744	    }
745	
746	    // Controls
747	    ctx.on(playPauseBtn, "click", togglePlayback);
748	
749	    const skipBack = ctx.el.querySelector<HTMLElement>("[data-skip-back]");
750	    const skipFwd = ctx.el.querySelector<HTMLElement>("[data-skip-forward]");
751	    if (skipBack) {
752	      ctx.on(skipBack, "click", () => {
753	        audio.currentTime = Math.max(0, audio.currentTime - SKIP_SECONDS);
754	      });
755	    }
756	    if (skipFwd) {
757	      ctx.on(skipFwd, "click", () => {
758	        const max = Number.isFinite(audio.duration)
759	          ? audio.duration
760	          : Number.POSITIVE_INFINITY;
761	        audio.currentTime = Math.min(max, audio.currentTime + SKIP_SECONDS);
762	      });
763	    }
764	
765	    const collapseToggle = ctx.el.querySelector<HTMLElement>(
766	      "[data-collapse-toggle]",
767	    );
768	    if (collapseToggle) {
769	      ctx.on(collapseToggle, "click", () => {
770	        playerPrefs.set({ collapsed: !playerPrefs.get().collapsed });
771	      });
772	    }
773	
774	    if (volSlider) {
775	      ctx.on(volSlider, "input", () => {
776	        playerPrefs.set({ volume: Number.parseFloat(volSlider.value) });
777	      });
778	    }
779	
780	    // Scrubbers (main + mini)
781	    const scrubMain = ctx.el.querySelector<HTMLElement>("[data-scrubber]");
782	    const scrubMini = ctx.el.querySelector<HTMLElement>("[data-scrubber-mini]");
783	    const seekToFraction = (f: number): void => {
784	      if (Number.isFinite(audio.duration))
785	        audio.currentTime = f * audio.duration;
786	    };
787	    for (const sc of [scrubMain, scrubMini]) {
788	      if (!sc) continue;
789	      const dispose = attachScrubber<number>({
790	        el: sc,
791	        indexAt: (clientX) => fractionAt(sc, clientX),
792	        preview: () => {},
793	        commit: seekToFraction,
794	      });
795	      ctx.onDestroy(dispose);
796	    }
797	
798	    // Time updates: progress bars + time display + position report.
799	    // Also kicks off the next-chapter prefetch once the user has clearly
800	    // committed to this chapter (>15% through). Doing it here, gated on
801	    // playback progress, means we don't waste bandwidth on chapters the
802	    // user opens and immediately abandons.
803	    const PREFETCH_TRIGGER_FRACTION = 0.15;
804	    ctx.on(audio, "timeupdate", () => {
805	      if (!audio.duration) return;
806	      const pct = (audio.currentTime / audio.duration) * 100;
807	      const fill = ctx.el.querySelector<HTMLElement>("[data-progress-fill]");
808	      if (fill) fill.style.width = `${pct}%`;
809	      const fillMini = ctx.el.querySelector<HTMLElement>(
810	        "[data-progress-fill-mini]",
811	      );
812	      if (fillMini) fillMini.style.width = `${pct}%`;
813	      updateTimeDisplay();
814	
815	      if (audio.currentTime / audio.duration > PREFETCH_TRIGGER_FRACTION) {
816	        tryStartPrefetch();
817	      }
818	
819	      const nowMs = Math.round(audio.currentTime * 1000);
820	      if (
821	        lastReportedMs < 0 ||
822	        Math.abs(nowMs - lastReportedMs) >= POSITION_REPORT_INTERVAL_MS
823	      ) {
824	        lastReportedMs = nowMs;
825	        const chapterId = ctx.dataset.chapterId;
826	        if (chapterId) {
827	          progress.observe({
828	            chapter_id: chapterId,
829	            audio_position_ms: nowMs,
830	          });
831	        }
832	      }
833	    });
834	
835	    // Play/pause icon — bound to the audio element's own state so it stays
836	    // in sync across morphdom patches (chapter swap re-renders #audio-player
837	    // and would otherwise reset the button text to the template default).
838	    ctx.bindElement(audio, ["play", "pause"], () => {
839	      playPauseBtn.textContent = audio.paused ? PLAY_GLYPH : PAUSE_GLYPH;
840	    });
841	
842	    // Side effects on play/pause that aren't DOM projection.
843	    ctx.on(audio, "play", () => {
844	      log("audio-play", {
845	        currentTime: audio.currentTime,
846	        duration: audio.duration,
847	      });
848	      scrollFollow.setPlaying(true);
849	      startHighlightLoop();
850	      if (ms) ms.playbackState = "playing";
851	      updateMediaSessionPosition();
852	    });
853	    ctx.on(audio, "pause", () => {
854	      log("audio-pause", {
855	        currentTime: audio.currentTime,
856	        duration: audio.duration,
857	        atEnd:
858	          Number.isFinite(audio.duration) &&
859	          audio.duration > 0 &&
860	          audio.currentTime >= audio.duration - 0.5,
861	      });
862	      scrollFollow.setPlaying(false);
863	      stopHighlightLoop();
864	      if (ms) ms.playbackState = "paused";
865	      const chapterId = ctx.dataset.chapterId;
866	      if (chapterId) {
867	        progress.observe({
868	          chapter_id: chapterId,
869	          audio_position_ms: Math.round(audio.currentTime * 1000),
870	        });
871	      }
872	    });
873	    ctx.on(audio, "ended", () => {
874	      log("audio-ended", {
875	        autoNext: readerSettings.get().autoNextChapter,
876	        hasPrefetchedBlob: prefetchedBlobUrl !== null,
877	        prefetchInFlight: prefetchAbort !== null,
878	        prefetchedFor,
879	        nextUrl: ctx.dataset.nextAudioUrl ?? null,
880	      });
881	      stopHighlightLoop();
882	      if (readerSettings.get().autoNextChapter) {
883	        // JS-side chapter swap on the same <audio> element. This is the
884	        // critical path for sleeping-mobile autoplay: a full LV navigation
885	        // would tear down the OS audio session and silently fail when the
886	        // device is locked. Same-element src swap keeps the lock-screen
887	        // controls live and the audio session uninterrupted.
888	        goToNextChapter();
889	      }
890	    });
891	    ctx.on(audio, "error", () => {
892	      const err = audio.error;
893	      log("audio-error", {
894	        code: err?.code ?? null,
895	        message: err?.message ?? null,
896	        currentSrc: audio.currentSrc?.startsWith("blob:") ? "blob" : "url",
897	      });
898	    });
899	    ctx.on(audio, "stalled", () =>
900	      log("audio-stalled", { currentTime: audio.currentTime }),
901	    );
902	    ctx.on(audio, "waiting", () =>
903	      log("audio-waiting", { currentTime: audio.currentTime }),
904	    );
905	    ctx.on(audio, "loadedmetadata", () =>
906	      log("audio-loadedmetadata", { duration: audio.duration }),
907	    );
908	
909	    // Re-sync UX
910	    if (resyncBtn) {
911	      ctx.on(resyncBtn, "click", () => {
912	        scrollFollow.resume();
913	        if (currentWordIndex >= 0 && textContainer) {
914	          const el = textContainer.querySelector<HTMLElement>(
915	            wordSelector(currentWordIndex),
916	          );
917	          el?.scrollIntoView({ behavior: "smooth", block: "center" });
918	        }
919	      });
920	    }
921	
922	    if (textContainer && "IntersectionObserver" in window) {
923	      intersectionObserver = new IntersectionObserver(
924	        (entries) => {
925	          for (const entry of entries) {
926	            if (entry.isIntersecting && scrollFollow.get().autoScrollPaused) {
927	              scrollFollow.resume();
928	            }
929	          }
930	        },
931	        { threshold: 0.5 },
932	      );
933	      ctx.onDestroy(() => intersectionObserver?.disconnect());
934	    }
935	
936	    ctx.bindStore(scrollFollow, (s) => {
937	      if (!resyncBtn) return;
938	      resyncBtn.classList.toggle("hidden", !s.autoScrollPaused);
939	    });
940	
941	    // Word menu actions
942	    ctx.on(window, "word-action", (detail) => {
943	      if (detail.kind === "play") seekToWordIndex(detail.index);
944	    });
945	
946	    // Speed badge cycle
947	    if (speedBadge) ctx.on(speedBadge, "click", () => cycleSpeed("up"));
948	
949	    // Keyboard-shortcut events
950	    ctx.on(window, "audio:toggle-playback", togglePlayback);
951	    ctx.on(window, "audio:toggle-mute", () => {
952	      audio.muted = !audio.muted;
953	    });
954	    ctx.on(window, "audio:change-speed", ({ direction }) =>
955	      cycleSpeed(direction),
956	    );
957	
958	    // Final cleanup not covered by ctx.on. Important: do NOT pause the
959	    // audio or revoke its current blob URL here. Destroy fires on LV
960	    // reconnect/re-mount (long phone sleep → server LV process times out
961	    // → client re-mount on wake) — and the <audio> element survives
962	    // (phx-update="ignore"). Pausing or revoking would interrupt the
963	    // user's listening session at exactly the moment they wake the phone
964	    // hoping playback continues. If the player is genuinely going away
965	    // (user navigates off the reader), the <audio> element gets removed
966	    // from the DOM, which auto-pauses it — no explicit pause needed.
967	    //
968	    // We do still abort and revoke the *prefetch* slot: that blob is not
969	    // tied to the playing audio element, so leaking it across re-mount
970	    // would just waste memory.
971	    ctx.onDestroy(() => {
972	      log("destroy", {
973	        audioPaused: audio.paused,
974	        currentTime: audio.currentTime,
975	        duration: audio.duration,
976	        prefetchInFlight: prefetchAbort !== null,
977	        hasPrefetchedBlob: prefetchedBlobUrl !== null,
978	      });
979	      stopHighlightLoop();
980	      wordMenuCleanup?.();
981	      if (prefetchAbort) prefetchAbort.abort();
982	      if (prefetchedBlobUrl) URL.revokeObjectURL(prefetchedBlobUrl);
983	    });
984	  },
985	);
