1	import { defineHook } from "../lib/hook";
2	import { attachScrubber, fractionAt } from "../lib/scrubber";
3	import { type Chapter, parseChapters } from "../lib/types";
4	
5	interface ChapterBarDataset {
6	  currentIndex: string;
7	  totalChapters: string;
8	  chapters: string;
9	  bookId: string;
10	}
11	
12	export const ChapterBarHook = defineHook<HTMLDivElement, ChapterBarDataset>(
13	  (ctx) => {
14	    const chapters = parseChapters(ctx.dataset.chapters);
15	    const currentIndex = Number.parseInt(ctx.dataset.currentIndex ?? "0", 10);
16	    const totalChapters = Number.parseInt(ctx.dataset.totalChapters ?? "0", 10);
17	
18	    const scrubberEl = ctx.el.querySelector<HTMLElement>(
19	      "[data-chapter-scrubber]",
20	    );
21	    const fill = ctx.el.querySelector<HTMLElement>("[data-scrubber-fill]");
22	    const thumb = ctx.el.querySelector<HTMLElement>("[data-scrubber-thumb]");
23	    const tooltip = ctx.el.querySelector<HTMLElement>(
24	      "[data-scrubber-tooltip]",
25	    );
26	    const strip = ctx.el.querySelector<HTMLElement>("[data-chapter-strip]");
27	    const indicator = document.getElementById("chapter-indicator");
28	
29	    const setScrubberPosition = (index: number): void => {
30	      const pct = totalChapters > 1 ? (index / (totalChapters - 1)) * 100 : 0;
31	      if (fill) fill.style.width = `${pct}%`;
32	      if (thumb) thumb.style.left = `${pct}%`;
33	    };
34	
35	    const scrollStripToIndex = (index: number): void => {
36	      if (!strip) return;
37	      const pill = strip.children[index];
38	      if (!(pill instanceof HTMLElement)) return;
39	      const stripRect = strip.getBoundingClientRect();
40	      const pillRect = pill.getBoundingClientRect();
41	      strip.scrollTo({
42	        left: pill.offsetLeft - stripRect.width / 2 + pillRect.width / 2,
43	        behavior: "smooth",
44	      });
45	    };
46	
47	    const indexAt = (clientX: number): number => {
48	      if (!scrubberEl) return 0;
49	      return Math.round(fractionAt(scrubberEl, clientX) * (totalChapters - 1));
50	    };
51	
52	    const showTooltip = (idx: number, clientX: number): void => {
53	      const ch: Chapter | undefined = chapters[idx];
54	      if (!ch || !tooltip || !scrubberEl) return;
55	      const label = ch.title ?? `Chapter ${ch.number}`;
56	      tooltip.textContent = `${idx + 1}. ${label}`;
57	      tooltip.classList.remove("hidden");
58	      const rect = scrubberEl.getBoundingClientRect();
59	      tooltip.style.left = `${((clientX - rect.left) / rect.width) * 100}%`;
60	    };
61	
62	    const hideTooltip = (): void => tooltip?.classList.add("hidden");
63	
64	    const jumpTo = (idx: number): void => {
65	      const target = chapters[idx];
66	      const current = chapters[currentIndex];
67	      if (!target || target.id === current?.id) return;
68	      ctx.pushEvent("jump_to_chapter", { chapter_id: target.id });
69	    };
70	
71	    setScrubberPosition(currentIndex);
72	    scrollStripToIndex(currentIndex);
73	
74	    if (scrubberEl) {
75	      const dispose = attachScrubber<number>({
76	        el: scrubberEl,
77	        indexAt,
78	        preview: (idx, clientX) => {
79	          setScrubberPosition(idx);
80	          scrollStripToIndex(idx);
81	          showTooltip(idx, clientX);
82	        },
83	        previewEnd: hideTooltip,
84	        commit: jumpTo,
85	      });
86	      ctx.onDestroy(dispose);
87	    }
88	
89	    let isOpen = false;
90	    const open = (): void => {
91	      ctx.el.classList.remove("scale-y-0", "opacity-0", "pointer-events-none");
92	      ctx.el.classList.add("scale-y-100", "opacity-100");
93	      isOpen = true;
94	    };
95	    const close = (): void => {
96	      ctx.el.classList.add("scale-y-0", "opacity-0", "pointer-events-none");
97	      ctx.el.classList.remove("scale-y-100", "opacity-100");
98	      isOpen = false;
99	    };
100	    const toggle = (): void => {
101	      if (isOpen) close();
102	      else open();
103	    };
104	
105	    if (indicator) ctx.on(indicator, "click", toggle);
106	
107	    ctx.on(window, "chapter-bar-close", () => {
108	      isOpen = false;
109	    });
110	
111	    ctx.on(document, "click", (e) => {
112	      if (!isOpen) return;
113	      const target = e.target;
114	      if (!(target instanceof Node)) return;
115	      if (ctx.el.contains(target)) return;
116	      if (target instanceof Element && target.id === "chapter-indicator")
117	        return;
118	      close();
119	    });
120	
121	    for (const pill of ctx.el.querySelectorAll<HTMLElement>(
122	      "[data-chapter-pill]",
123	    )) {
124	      ctx.on(pill, "click", () => {
125	        const idx = Number.parseInt(pill.dataset.chapterPill ?? "-1", 10);
126	        jumpTo(idx);
127	      });
128	    }
129	  },
130	);
