1	/**
2	 * Audio auto-next-chapter test.
3	 *
4	 * Verifies the chapter swap on `ended` keeps the same <audio> element and
5	 * uses LiveView push_patch (no full navigation). This is the critical
6	 * mobile-lock-screen fix: a full navigation tears down the OS audio
7	 * session, which is why autoplay used to fail when the phone was asleep.
8	 *
9	 * Requires the canonical e2e fixture: a chapter with audio that *also*
10	 * has a next chapter with audio (so `next_audio_url` is populated).
11	 * `seed_e2e_book!/1` defaults to `audio_for: [1, 2]` — chapter 1 sees
12	 * chapter 2 as the next audio-ready chapter.
13	 */
14	import { describe, it, before, after } from "node:test";
15	import assert from "node:assert";
16	import { setup, teardown, openReader, BASE_URL } from "../helpers.js";
17	
18	describe("Audio auto-next-chapter", () => {
19		let browser, page;
20	
21		before(async () => {
22			({ browser, page } = await setup());
23	
24			// Find a chapter that has audio AND a next-chapter audio URL.
25			// The fixture guarantees chapter 1 satisfies this; we still walk
26			// the bar in case the test ordering shifted.
27			await openReader(page);
28			const chapters = await page.evaluate(() => {
29				const bar = document.getElementById("chapter-bar");
30				return bar ? JSON.parse(bar.dataset.chapters) : [];
31			});
32	
33			const bookId = page.url().match(/\/books\/(\d+)\/read/)?.[1];
34			assert.ok(bookId, "openReader must land on a /books/:id/read/:cid URL");
35			assert.ok(
36				chapters.length > 0,
37				"fixture must seed ≥1 chapter; check ReadaloudAudiobook.Fixtures.E2E.seed!/1",
