3	function isEditableTarget(target: EventTarget | null): boolean {
4	  if (!(target instanceof HTMLElement)) return false;
5	  return (
6	    target.tagName === "INPUT" ||
7	    target.tagName === "TEXTAREA" ||
8	    target.isContentEditable
9	  );
10	}
11	
12	export const KeyboardShortcutsHook = defineHook((ctx) => {
13	  ctx.on(window, "keydown", (e) => {
14	    if (isEditableTarget(e.target)) return;
15	
16	    switch (e.key) {
17	      case " ":
18	        e.preventDefault();
19	        ctx.dispatch("audio:toggle-playback");
20	        return;
21	      case "ArrowLeft":
22	        e.preventDefault();
23	        ctx.pushEvent("prev_chapter");
24	        return;
